WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (696::BIGINT, 'Este señor no da clases.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2025-10-28T00:00:00+00:00'::TIMESTAMPTZ, '68737e56889011f14d4679f4262b2eef910af39c939f270ff71055c20ef82c95'::TEXT, ARRAY[2971]::BIGINT[]),
    (696::BIGINT, 'Barboza logra crear un ambiente muy positivo en un curso tan complejo como funda. Explica con mucha claridad y siempre se nota su disposición para ayudar. Ojalá nunca deje de ser esa gran persona y excelente profe. Para mí, fue el mejor profe de este semestre'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2025-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'd942699fb5e5c62758d8c7f965e536ddc452a1ae9f54deaa554586b155572299'::TEXT, ARRAY[2961]::BIGINT[]),
    (696::BIGINT, 'muy crack, explica muy muy bien'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-03T00:00:00+00:00'::TIMESTAMPTZ, '57800d438f52122267c28082ba71676b77d3da881d6abb9165f99fca91e3d319'::TEXT, ARRAY[2961]::BIGINT[]),
    (696::BIGINT, 'Si no fuera por Barboza, yo no paso este curso. Explica muy bien los temas, la materia, lo que quiere para los proyectos, y las bases del hardware requerido para este curso. Recomendable llegar todos los días para resolver dudas, y no dejar los talleres y proyectos para el último día'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-02-08T00:00:00+00:00'::TIMESTAMPTZ, '9e609787cf9a2c42b3d41ef1b6c4518e2de4add66a368b589debce4e13f4cfbe'::TEXT, ARRAY[2971]::BIGINT[]),
    (696::BIGINT, 'El curso es posiblemente el que da más pereza de toda la carrera. Evaluaciones que piden cosas sin sentido, proyectos largos, tediosos y aburridos. El profe intenta hacerlo llevadero, pero hasta a él se le nota la pereza de dar ese curso entonces tampoco puede hacer mucho.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-11T00:00:00+00:00'::TIMESTAMPTZ, '75ec2876291221722a6f9d3347e6fa4ca53c3d5e78b292def8e7f536889ce6fa'::TEXT, ARRAY[2982]::BIGINT[]),
    (696::BIGINT, 'El profe de verdad es el mejor, ayuda muchísimo al estudiante, es bastante accesible y abarca los temas de forma muy clara y sin abrumar. Si tiene la oportunidad no dude matricular con el'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '01068d713a9417524882ba307b321f4ab9098bc2fa7d3bec91820f97450b2d7a'::TEXT, ARRAY[2961]::BIGINT[]),
    (696::BIGINT, 'Es una excelente persona y un excelente profe. Las clases son entretenidas, ayuda al estudiante y explica muy bien. No lo dude si puede matricular con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-24T00:00:00+00:00'::TIMESTAMPTZ, '5f1be6b2702c472c9a7ecd4be5bd4c4a87b85814d13bdc195de35480e954bbda'::TEXT, ARRAY[2962]::BIGINT[]),
    (696::BIGINT, 'El profe es muy relax, explica bien, las evaluaciones quedan claras y trata de ayudar en lo más que se pueda. Si tiene la oportunidad de llevarlo con él, se los recomiendo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'f2cee73bccc3350a787b71c56db094aa9a12dcd71815025dbf0a510311183a00'::TEXT, ARRAY[2983]::BIGINT[]),
    (696::BIGINT, 'Muy agradable aunque a veces no sabe bien por qué no dan los resultados en el laboratorio, resultando en laboratorios incompletos o simulados, califica suave y se aprende bastante.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-12-17T00:00:00+00:00'::TIMESTAMPTZ, '0041c34065fae54643c03290282dac3e280176893c7856c955f7d4e95b8bbf95'::TEXT, ARRAY[2968]::BIGINT[]),
    (696::BIGINT, 'Es el mejor profe que he tenido en la U, siempre vela por el estudiante y siempre esta dispuesto a explicar//ayudar sin duda es la mejor opcion para matricular en cualquier curso'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-25T00:00:00+00:00'::TIMESTAMPTZ, '032d3fe07b876889b780aa6d4ee01046602e314bb700220e386694197c4c688a'::TEXT, ARRAY[2962]::BIGINT[]),
    (696::BIGINT, 'Uno de los mejores profesores que he tenido durante mi trayecto en el Tecnológico, calidad de persona, comprensible, siempre dispuesto a brindar ayuda a los estudiantes y muy humilde.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'ad0952df036a49b6a9e978f9278a5ac40c0d44bb614de075c8f86b783bfdc112'::TEXT, ARRAY[2968]::BIGINT[]),
    (696::BIGINT, 'Es un profe super bueno, en lo personal aprendí mucho con él. Dado que está joven entiende mucho a los estudiantes ya que les tiene mucha empatía. Sabe mucho, y brinda mucha ayuda si se la solicitas ,es del tipo de profe que no avanza de tema si no entienden todos. Espero volver a llevar con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2022-04-06T00:00:00+00:00'::TIMESTAMPTZ, '62c05a6bae09faa0ecb070fb1b175deec2a08fcb333e808d200a8474f2d59e9f'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (696::BIGINT, 'Demasiado buen profesor, si tienes dudas o problemas con algo el intenta ayudar en todo lo que esta a su alcance, muy gente con los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, '32a0c001b6c9f7bbba5c6530e6ae78523549180996e15e12b7b861a9ee4a5de7'::TEXT, ARRAY[2968]::BIGINT[]),
    (696::BIGINT, 'Buen profe muy buena gente y comprensivo, responde las dudas siempre que puede pero no es tan inmediato. Algunas cosas son enredadas pero creo que es más por virtualidad que por el profe. Los quices normal, se debe preparar para ellos. Califica bastante justo y la retroalimentación es clara.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Aspectos de calificación claros']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'c6e250e3ce8f81b883eda1f4c8afd3665f6652028eaf3520cda0f47186f69fce'::TEXT, ARRAY[2968]::BIGINT[]),
    (696::BIGINT, 'Es más relajado que el otro profe, califica más suave, aveces se enrede y no tiene claro algunos conceptos'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo']::TEXT[], '2021-09-24T00:00:00+00:00'::TIMESTAMPTZ, 'be171d2bd26ee57272dc4bca39d2ad7e01c813725490b1a60c9b7436e2ce5fe2'::TEXT, ARRAY[2971]::BIGINT[]),
    (696::BIGINT, 'El profe se pierde un poco y no tiene ciertos terminos bien claros. Pero realmente es buena gente y ayuda, explica mil veces si uno se lo pide.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-27T00:00:00+00:00'::TIMESTAMPTZ, 'c54b63212bd2e664ce761c7a72e918c4f9a07d468c8fe6fb8f94b63967160b0e'::TEXT, ARRAY[2982]::BIGINT[]),
    (696::BIGINT, 'Es un buen profesor, sabe mucho y ayuda mucho cuando se tienen dudas ya sea durante la clase o fuera de clase, responde normalmente rápido, deja bastantes tareas pero la mayoría son cortas y ayuda bastante ya que se divide el porcentaje mucho, los exámenes si tienen su grado de dificultad.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '9c434d1a5553a3b79ca005864291f6df2c540480848fcc8437382b06904c710c'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (696::BIGINT, 'Las clases son super relajantes, uno solo va a prestar atención y la mayoría de lecciones son cortas. Solo que si quieren que él profe les considere dar más tiempo para entregar la progra tienen que estarle escribiendo dudas de la progra para que él sepa que están pegados.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '686a8dac1bff3e9fa08ed91743c152524d6f742498231b605e921d12f019665f'::TEXT, ARRAY[2982]::BIGINT[]),
    (696::BIGINT, 'Es muy buen profesor, comprensivo, explica muy bien. Si usted es alguien discplinado y constante le va a ir súper bien. El profe brinda mucho apoyo a los estudiantes y siempre que uno le pregunte, aclara dudas. Volvería a matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '1ff22ea91388054002b5c359d84807e26736668b65c711acbe27465808cf0ccf'::TEXT, ARRAY[2511]::BIGINT[]),
    (696::BIGINT, 'El profe se esfuerza por dar un buen curso, siempre está atento a los estudiantes. Los enunciados nunca son claros, pero si se le pregunta trata de guiar y al final califica como bueno si el vio interés y constancia. Es una gran persona y da consejos para la carrera.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '03d51862a725e2c9074e1bcbf3a8c0101770b43aa733dd5504dc907e4eaaf9fc'::TEXT, ARRAY[2982]::BIGINT[]),
    (696::BIGINT, 'Es buen profesor y siempre está anuente a atenderlo a uno. Es cierto que las tareas que deja no se entienden bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'bda75f407a97bdefa6b115e5da07cd590418593bf9658afb2722894a39e52e19'::TEXT, ARRAY[2982]::BIGINT[]),
    (696::BIGINT, 'Clases aburridas y monótonas. No redacta bien algunas cosas por lo que cuesta entender. Se enreda solo cuando uno le pregunta de las tareas y se contradice. No es bueno en consulta. Trata de darse a entender lo mejor posible pero le cuesta.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2020-10-07T00:00:00+00:00'::TIMESTAMPTZ, '15950a19f46d6fef8f375f5cf66e721fbadf4c8d3e0b89cccb0756934c7684bf'::TEXT, ARRAY[2982]::BIGINT[]),
    (696::BIGINT, 'El profe en si se esfuerza mucho por darse a entender y siempre está abierto a dudas, deja mucha práctica y tareas lo cual es bueno para practicar para el examen. Es un profe con poca experiencia, pero es bueno.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Brinda apoyo']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'e75e9967890a1c91ef6bb04811b5d0e8bc458cc9ce5ad2e830321476b6022299'::TEXT, ARRAY[2511]::BIGINT[]),
    (696::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '647ae95efc2a50f9c1c86ffd6015fd45d16fcdc40195c843ec0c27d96da10fd6'::TEXT, ARRAY[2511]::BIGINT[]),
    (696::BIGINT, 'EL profe no es bueno en consulta. Deja muchos talleres que al final no son revisados bien. Me gusta mucho que hace práctica antes del examen. Las clases son solo leer las presentaciones.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'ab989f1fae3558ffb678b06805b5a2bbc1cba558f690835e3fde50cf06151440'::TEXT, ARRAY[2982]::BIGINT[]),
    (696::BIGINT, 'El profe se la juega, pero explica cosas muy fáciles en clases y deja exámenes mu8y difíciles'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, 'b68cf56f1bfd5a9ee733db3c8031c8a198b55684a819d8fa5ac12048a61ea5ae'::TEXT, ARRAY[2511]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
